// Both triggers land here. Remember which one fired so the tail of the
// workflow knows whether a webhook is waiting for a response.
const item = $input.first().json;
const fromWebhook = item.body !== undefined;
const topic = fromWebhook ? (item.body.topic || 'sweep') : 'sweep';

return [{ json: { topic, fromWebhook, startedAt: new Date().toISOString() } }];

const findings = $('Scout').first().json.output;
const analysis = $('Analyst').first().json.output;
const meta = $('Normalise Input').first().json;

return [{ json: {
  topic: meta.topic,
  fromWebhook: meta.fromWebhook,
  startedAt: meta.startedAt,
  finishedAt: new Date().toISOString(),
  findings,
  analysis
} }];

// Scheduled run — nobody is waiting on a response. The result sits in the
// execution log for the hub to read back when asked.
// To get it pushed somewhere instead, wire a Gmail or Slack node here.
console.log('Scheduled sweep complete:', $json.topic);
return $input.all();
